UPDATE knowledge_proposals SET
state=#{state},revision=revision+1,reviewed_by=#{actor},reviewed_at=#{at},review_note=#{note},published_version=#{version}
WHERE shop_id=#{shop} AND id=#{id}

UPDATE knowledge_proposals SET base_version=#{base},snapshot=#{snapshot},state='draft',
  revision=revision+1,reviewed_by=NULL,reviewed_at=NULL,review_note=NULL,published_version=NULL
WHERE shop_id=#{shop} AND id=#{id}
